CBaseAllocator::~CBaseAllocator()
{
    if (m_hSem != 0)
        CloseHandle(m_hSem);
    if (m_pNotify)
        m_pNotify->Release();
}

// ---- stubs and driver ----
#pragma comment(lib, "kernel32.lib")
extern "C" __declspec(dllimport) void __stdcall InitializeCriticalSection(_RTL_CRITICAL_SECTION_Retail* cs);
extern "C" __declspec(dllimport) void* __stdcall CreateSemaphoreA(void* attributes, long initial, long maximum, const char* name);
extern "C" __declspec(dllimport) int __stdcall GetHandleInformation(void* handle, unsigned long* flags);
// stubs: CBaseObject's destructor records its `this` and the call order; the notify callback counts Release calls
static int g_seq = 0, g_baseSeq = 0, g_releaseSeq = 0, g_baseCalls = 0, g_releases = 0;
static const void* g_baseThis = 0; static const void* g_releaseThis = 0;
CBaseObject::~CBaseObject() { ++g_baseCalls; g_baseThis = this; g_baseSeq = ++g_seq; }
struct Notify : IMemAllocatorNotifyCallbackTemp {
    long __stdcall QueryInterface(const void*, void**) { return -1; }
    unsigned long __stdcall AddRef() { return 2; }
    unsigned long __stdcall Release() { ++g_releases; g_releaseThis = this; g_releaseSeq = ++g_seq; return 0; }
};
static void Reset() { g_seq = g_baseSeq = g_releaseSeq = g_baseCalls = g_releases = 0; g_baseThis = g_releaseThis = 0; }
int main()
{
    static double raw[12];                         // 0x60 bytes: the CBaseAllocator object
    unsigned char* b = (unsigned char*)raw;
    CBaseAllocator* a = (CBaseAllocator*)raw;
    CHECK(sizeof(CBaseAllocator) == 0x60);
    // semaphore and notify callback set: the handle is closed, the callback released, then the CBaseObject base destroyed
    Reset(); memset(raw, 0, sizeof raw);
    InitializeCriticalSection((_RTL_CRITICAL_SECTION_Retail*)(b + 0x10));
    void* sem = CreateSemaphoreA(0, 0, 4, 0);
    unsigned long flags = 0;
    CHECK(sem != 0 && GetHandleInformation(sem, &flags) != 0);
    static Notify n;
    *(void**)(b + 0x30) = sem;
    *(Notify**)(b + 0x58) = &n;
    a->CBaseAllocator::~CBaseAllocator();
    CHECK(GetHandleInformation(sem, &flags) == 0);   // closed
    CHECK(g_releases == 1 && g_releaseThis == &n);
    CHECK(g_baseCalls == 1 && g_baseThis == b + 4);
    CHECK(g_releaseSeq == 1 && g_baseSeq == 2);
    // neither set: only the bases are destroyed
    Reset(); memset(raw, 0, sizeof raw);
    InitializeCriticalSection((_RTL_CRITICAL_SECTION_Retail*)(b + 0x10));
    a->CBaseAllocator::~CBaseAllocator();
    CHECK(g_releases == 0 && g_baseCalls == 1 && g_baseThis == b + 4);
    // only the callback set
    Reset(); memset(raw, 0, sizeof raw);
    InitializeCriticalSection((_RTL_CRITICAL_SECTION_Retail*)(b + 0x10));
    *(Notify**)(b + 0x58) = &n;
    a->CBaseAllocator::~CBaseAllocator();
    CHECK(g_releases == 1 && g_baseCalls == 1 && g_releaseSeq == 1 && g_baseSeq == 2);
    if (fails == 0) printf("00ca9d00_TEST PASS\n");
    return fails;
}
